"use client";

import {
  motion,
  useScroll,
  useSpring,
  useTransform,
} from "motion/react";

import { useRef } from "react";

export function Hero() {
  const sectionRef =
    useRef<HTMLElement>(null);

  const { scrollYProgress } =
    useScroll({
      target: sectionRef,
      offset: [
        "start start",
        "end start",
      ],
    });

  const progress = useSpring(
    scrollYProgress,
    {
      stiffness: 90,
      damping: 30,
      mass: 0.45,
    }
  );

  const giantX = useTransform(
    progress,
    [0, 1],
    ["0%", "-28%"]
  );

  const titleY = useTransform(
    progress,
    [0, 1],
    ["0%", "-38%"]
  );

  const titleScale = useTransform(
    progress,
    [0, 0.75],
    [1, 0.78]
  );

  const titleOpacity = useTransform(
    progress,
    [0, 0.78],
    [1, 0]
  );

  const coreY = useTransform(
    progress,
    [0, 1],
    ["0%", "22%"]
  );

  const coreScale = useTransform(
    progress,
    [0, 1],
    [1, 1.45]
  );

  const coreRotate = useTransform(
    progress,
    [0, 1],
    [0, 18]
  );

  const ringScale = useTransform(
    progress,
    [0, 1],
    [1, 1.75]
  );

  return (
    <section
      ref={sectionRef}
      className="lawx-hero"
    >
      <div className="lawx-hero-sticky">
        <div className="lawx-hero-grid" />

        <motion.div
          className="lawx-giant-word"
          style={{ x: giantX }}
        >
          LAWXYGEN LAWXYGEN
        </motion.div>

        <div className="lawx-hero-content-wrap">
          <motion.div
            className="lawx-hero-copy"
            style={{
              y: titleY,
              scale: titleScale,
              opacity: titleOpacity,
            }}
          >
            <motion.div
              className="lawx-kicker"
              initial={{
                opacity: 0,
                y: 25,
              }}
              animate={{
                opacity: 1,
                y: 0,
              }}
              transition={{
                duration: 0.8,
                delay: 0.15,
              }}
            >
              <span />
              LEGAL · TAX · BUSINESS
            </motion.div>

            <h1>
              <span className="lawx-mask">
                <motion.b
                  initial={{
                    y: "115%",
                  }}
                  animate={{ y: 0 }}
                  transition={{
                    duration: 1,
                    delay: 0.1,
                    ease: [
                      0.16,
                      1,
                      0.3,
                      1,
                    ],
                  }}
                >
                  Breathe
                </motion.b>
              </span>

              <span className="lawx-mask">
                <motion.b
                  initial={{
                    y: "115%",
                  }}
                  animate={{ y: 0 }}
                  transition={{
                    duration: 1,
                    delay: 0.2,
                    ease: [
                      0.16,
                      1,
                      0.3,
                      1,
                    ],
                  }}
                >
                  legal
                </motion.b>
              </span>

              <span className="lawx-mask">
                <motion.b
                  className="lawx-blue-word"
                  initial={{
                    y: "115%",
                  }}
                  animate={{ y: 0 }}
                  transition={{
                    duration: 1,
                    delay: 0.3,
                    ease: [
                      0.16,
                      1,
                      0.3,
                      1,
                    ],
                  }}
                >
                  ease.
                </motion.b>
              </span>
            </h1>

            <motion.div
              className="lawx-hero-description"
              initial={{
                opacity: 0,
                y: 25,
              }}
              animate={{
                opacity: 1,
                y: 0,
              }}
              transition={{
                duration: 0.9,
                delay: 0.6,
              }}
            >
              <p>
                From starting a company to
                protecting its future,
                LAWXYGEN turns complex legal
                work into a clear digital
                experience.
              </p>

              <div className="lawx-hero-buttons">
                <button
                  type="button"
                  onClick={() =>
                    document
                      .querySelector(
                        ".lawx-search-services"
                      )
                      ?.dispatchEvent(
                        new MouseEvent(
                          "click",
                          {
                            bubbles: true,
                          }
                        )
                      )
                  }
                >
                  Explore Services
                  <span>↗</span>
                </button>

                <a href="#contact">
                  Talk to an Expert
                  <span>→</span>
                </a>
              </div>
            </motion.div>
          </motion.div>

          <motion.div
            className="lawx-core"
            style={{
              y: coreY,
              scale: coreScale,
              rotate: coreRotate,
            }}
          >
            <motion.div
              className="lawx-core-ring ring-1"
              style={{
                scale: ringScale,
              }}
            />

            <motion.div
              className="lawx-core-ring ring-2"
              style={{
                scale: ringScale,
              }}
            />

            <div className="lawx-core-glow" />

            <div className="lawx-core-center">
              <span>259</span>
              <small>SERVICES</small>
            </div>

            <div className="lawx-orbit-label orbit-1">
              <i />
              Business
            </div>

            <div className="lawx-orbit-label orbit-2">
              <i />
              Compliance
            </div>

            <div className="lawx-orbit-label orbit-3">
              <i />
              IP
            </div>
          </motion.div>
        </div>

        <div className="lawx-color-dots">
          <i />
          <i />
          <i />
        </div>

        <div className="lawx-scroll-indicator">
          <span>SCROLL</span>
          <b />
        </div>
      </div>
    </section>
  );
}